drop policy if exists secondary_staff_module_settings_read on public.secondary_staff_module_settings;
drop policy if exists secondary_staff_module_settings_insert on public.secondary_staff_module_settings;
drop policy if exists secondary_staff_module_settings_update on public.secondary_staff_module_settings;
drop policy if exists secondary_staff_module_settings_delete on public.secondary_staff_module_settings;
create policy secondary_staff_module_settings_read on public.secondary_staff_module_settings for select to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_module_settings.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher','bursar')));
create policy secondary_staff_module_settings_insert on public.secondary_staff_module_settings for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_module_settings.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','bursar')));
create policy secondary_staff_module_settings_update on public.secondary_staff_module_settings for update to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_module_settings.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','bursar'))) with check(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_module_settings.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','bursar')));
create policy secondary_staff_module_settings_delete on public.secondary_staff_module_settings for delete to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_module_settings.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin')));